using System.Security.Claims;using System.Text.Json;using HealthTracker.Api.Contracts;using HealthTracker.Api.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace HealthTracker.Api.Controllers;[Authorize][ApiController][Route("api/patient")]public class PatientController(AppDbContext db):ControllerBase{Guid U=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpGet]public async Task<IActionResult> Get(){var p=await db.Patients.SingleAsync(x=>x.UserId==U);return Ok(new{p.Id,p.Name,p.Dob,Conditions=JsonSerializer.Deserialize<List<string>>(p.ConditionsJson)??[],p.Notes,p.Relationship});}[HttpPut]public async Task<IActionResult> Put(PatientRequest r){var p=await db.Patients.SingleAsync(x=>x.UserId==U);p.Name=r.Name.Trim();p.Dob=string.IsNullOrWhiteSpace(r.Dob)?null:DateOnly.Parse(r.Dob);p.ConditionsJson=JsonSerializer.Serialize(r.Conditions);p.Notes=r.Notes;p.Relationship=r.Relationship;await db.SaveChangesAsync();return Ok(new{p.Id,p.Name,p.Dob,Conditions=r.Conditions,p.Notes,p.Relationship});}}